// Eingaben normalisieren und Lead-ID vergeben.
// Kein globales URL-Objekt: der n8n-Task-Runner stellt es nicht bereit.
const f = $input.first().json;

let url = String(f.Website || '').trim();
if (!/^https?:\/\//i.test(url)) url = 'https://' + url;

const treffer = /^https?:\/\/([^\/?#]+)/i.exec(url);
if (!treffer || !treffer[1] || /\s/.test(treffer[1])) {
  throw new Error('Keine gueltige Adresse: ' + f.Website);
}
const host = treffer[1].replace(/^www\./i, '');

const heute = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const kurz = String(f.Firma || host)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 24);

return [{
  json: {
    lead_id: 'L-' + heute + '-' + kurz,
    firma: f.Firma || null,
    website: url,
    host: host,
    ort: f.Ort || null,
    branche: f.Branche || null,
    ansprechpartner: f.Ansprechpartner || null,
    anrede: String(f.Anrede || 'Sie').toLowerCase() === 'du' ? 'du' : 'sie',
    keyword: f.Keyword || null,
    notiz: f.Notiz || null
  }
}];

// Leichter Sofort-Check ohne Browser: Erreichbarkeit, Redaktionssystem,
// Impressum verlinkt, anwaehlbare Telefonnummer, Rechtsstand des Impressums.
// Die Tiefenanalyse mit Playwright laeuft spaeter lokal.
const lead = $('Lead vorbereiten').first().json;
const res = $input.first().json || {};

const status = res.statusCode ?? null;
const html = typeof res.body === 'string' ? res.body : (typeof res.data === 'string' ? res.data : '');
const erreichbar = status !== null && status < 400 && html.length > 200;

const titel = (/<title[^>]*>([\s\S]{0,200}?)<\/title>/i.exec(html)?.[1] || '').replace(/\s+/g, ' ').trim();
const generator = /<meta[^>]+name=["']generator["'][^>]+content=["']([^"']+)/i.exec(html)?.[1] || null;

let cms = generator;
if (!cms && /wp-content|wp-includes/i.test(html)) cms = 'WordPress';
if (!cms && /\/typo3(conf|temp)\//i.test(html)) cms = 'TYPO3';
if (!cms && /\/_astro\//i.test(html)) cms = 'Astro';
if (!cms && /_next\/static/i.test(html)) cms = 'Next.js';

const theme = /wp-content\/themes\/([A-Za-z0-9_-]+)/i.exec(html)?.[1] || null;
const telLinks = (html.match(/href=["']tel:/gi) || []).length;
const hatImpressum = /href=["'][^"']*(impressum|imprint|anbieterkennzeichnung)/i.test(html);
const hatDatenschutz = /href=["'][^"']*(datenschutz|privacy)/i.test(html);
const hatViewport = /<meta[^>]+name=["']viewport["']/i.test(html);
const zoomGesperrt = /user-scalable\s*=\s*(no|0)|maximum-scale\s*=\s*1(?![\d.])/i.test(html);
const hatJsonLd = /application\/ld\+json/i.test(html);
const hatOg = /property=["']og:/i.test(html);
const hatDescription = /<meta[^>]+name=["']description["']/i.test(html);
const copyright = /(?:©|&copy;|Copyright)\s*(?:\d{4}\s*[-–]\s*)?(\d{4})/i.exec(html)?.[1] || null;

// Grobe Einschaetzung, ob sich die Tiefenanalyse lohnt.
let punkte = 0;
if (telLinks === 0) punkte += 3;
if (!hatJsonLd) punkte += 2;
if (!hatDescription) punkte += 2;
if (!hatOg) punkte += 1;
if (zoomGesperrt) punkte += 2;
if (!hatViewport) punkte += 2;
if (copyright && (new Date().getFullYear() - Number(copyright)) >= 3) punkte += 3;
if (theme && /divi|avada|enfold|betheme|bridge/i.test(theme)) punkte += 1;

const urteil = !erreichbar ? 'nicht erreichbar'
  : punkte >= 8 ? 'lohnt sich'
  : punkte >= 4 ? 'wahrscheinlich lohnend'
  : 'eher unauffaellig';

const zeilen = [];
zeilen.push('*' + (lead.firma || lead.host) + '*');
if (!erreichbar) {
  zeilen.push('Seite nicht erreichbar (Status ' + (status ?? 'keine Antwort') + ')');
} else {
  zeilen.push('Status ' + status + (cms ? ' · ' + cms : '') + (theme ? ' / ' + theme : ''));
  if (titel) zeilen.push('Titel: ' + titel.slice(0, 70));
  const m = [];
  m.push(telLinks === 0 ? 'keine anwaehlbare Nummer' : telLinks + ' Telefonlinks');
  m.push(hatImpressum ? 'Impressum verlinkt' : 'kein Impressum verlinkt');
  if (!hatDatenschutz) m.push('keine Datenschutzerklaerung verlinkt');
  if (!hatDescription) m.push('keine Meta-Description');
  if (!hatJsonLd) m.push('keine strukturierten Daten');
  if (zoomGesperrt) m.push('Zoom gesperrt');
  if (copyright) m.push('Fusszeile ' + copyright);
  zeilen.push(m.join(' · '));
}
zeilen.push('');
zeilen.push('Einschaetzung: *' + urteil + '*');
zeilen.push('Lead: ' + lead.lead_id);

return [{
  json: {
    // Spaltennamen entsprechen exakt dem Blatt "Leads".
    lead_id: lead.lead_id,
    firma: lead.firma,
    website: lead.website,
    ort: lead.ort,
    branche: lead.branche,
    ansprechpartner: lead.ansprechpartner,
    anrede: lead.anrede,
    mail: '',
    telefon: '',
    kontaktquelle: 'website',
    website_score: '',
    akquise_score: '',
    akquise_ansatz: '',
    compliance: '',
    status: 'neu',
    next_action: 'analyse',
    next_action_at: new Date().toISOString().slice(0, 10),
    email_freigabe: 'nein',
    email_freigabe_am: '',
    email_freigabe_notiz: '',
    gmail_draft_id: '',
    gmail_thread_id: '',
    gmail_empfaenger: '',
    gmail_betreff: '',
    unterlagen_gesendet_am: '',
    ende_grund: '',
    wiedervorlage_am: '',
    notiz: lead.notiz || '',
    berichte_pfad: '',
    // Nur fuer die Telegram-Nachricht, nicht fuer das Blatt.
    _meldung: zeilen.join('\n'),
    _keyword: lead.keyword
  }
}];

const ERWARTETES_TOKEN = 'TOKEN_HIER';
  const eingang = $input.first().json;
  const kopf = eingang.headers || {};
  const d = eingang.body || eingang;
  if (ERWARTETES_TOKEN === 'TOKEN' + '_HIER') throw new Error('Webhook-Token ist noch nicht konfiguriert');
  if (kopf['x-akquise-token'] !== ERWARTETES_TOKEN) throw new Error('Token stimmt nicht');
  for (const feld of ['lead_id', 'audit_id', 'website']) {
    if (!d[feld]) throw new Error('Pflichtfeld fehlt: ' + feld);
  }
  const zahl = (v) => (Number.isFinite(Number(v)) ? Number(v) : '');
  const a = d.achsen || {};
  const erwarteteTypen = new Map([
    ['intern', 'md'], ['telefon', 'md'], ['mail', 'md'], ['kunde', 'html'],
  ]);
  const berichte = Array.isArray(d.berichte) ? d.berichte : [];
  if (berichte.length !== 4) throw new Error('Genau vier Berichte erwartet');
  const gesehen = new Set();
  const datum = String(d.audit_id).slice(0, 10);
  for (const bericht of berichte) {
    const match = /^(\d{4}-\d{2}-\d{2})_(intern|telefon|mail|kunde)\.(md|html)$/.exec(String(bericht.dateiname || ''));
    if (!match || match[1] !== datum || erwarteteTypen.get(match[2]) !== match[3]) {
      throw new Error('Ungueltiger Berichtsname: ' + String(bericht.dateiname || ''));
    }
    if (gesehen.has(match[2])) throw new Error('Doppelter Berichtstyp: ' + match[2]);
    gesehen.add(match[2]);
    const base64 = String(bericht.inhalt_base64 || '');
    if (!base64 || base64.length % 4 !== 0 || !/^[A-Za-z0-9+/]+={0,2}$/.test(base64)) {
      throw new Error('Bericht ist nicht korrekt Base64-kodiert: ' + bericht.dateiname);
    }
    if (base64.length > 2796212) throw new Error('Bericht ist groesser als 2 MB: ' + bericht.dateiname);
  }
  const leadZeile = {
    lead_id: d.lead_id, firma: d.firma || '', website: d.website,
    ort: d.ort || '', branche: d.branche || '',
    ansprechpartner: d.ansprechpartner || '', anrede: d.anrede || 'sie',
    mail: d.mail || '', telefon: d.telefon || '',
    kontaktquelle: d.kontaktquelle || 'website',
    website_score: zahl(d.website_score), akquise_score: zahl(d.akquise_score),
    akquise_ansatz: d.akquise_ansatz || '', compliance: d.compliance || '',
    status: 'analysiert', next_action: 'anruf',
    next_action_at: new Date().toISOString().slice(0, 10),
    notiz: (d.argumente || []).map((x) => x.kurz).join(' | ').slice(0, 500),
    berichte_pfad: d.berichte_pfad || '', berichte_drive_url: '',
    mail_betreff: d.mail_betreff || '',
    mail_entwurf: (d.mail_entwurf || '').slice(0, 45000),
  };
  const auditZeile = {
    audit_id: d.audit_id, lead_id: d.lead_id, datum: new Date().toISOString(),
    collector_version: d.collector_version || '',
    regelwerk_version: d.regelwerk_version || '',
    website_score: zahl(d.website_score), akquise_score: zahl(d.akquise_score),
    seo: zahl(a.seo), technik: zahl(a.technik), air: zahl(a.air),
    design: zahl(a.design), conversion: zahl(a.conversion),
    local: zahl(a.local), vertrauen: zahl(a.vertrauen),
    compliance: d.compliance || '', seiten_geprueft: zahl(d.seiten_geprueft),
    pfad: d.berichte_pfad || '',
  };
  return [{ json: {
    leadZeile, auditZeile, berichte,
    empfehlung: d.akquise_empfehlung || '',
  } }];

const eingang = $('Nutzlast pruefen').first().json.leadZeile;
  const treffer = $input.all().map((item) => item.json).filter((row) => row && row.lead_id);
  if (treffer.length > 1) throw new Error('Mehrere Sheet-Zeilen fuer Lead ' + eingang.lead_id);
  if (!treffer.length) return [{ json: eingang }];
  const aktuell = treffer[0];
  const status = String(aktuell.status || '');
  const istNeu = !status || status === 'neu';
  return [{ json: {
    ...eingang,
    status: istNeu ? 'analysiert' : status,
    next_action: istNeu ? 'anruf' : (aktuell.next_action || ''),
    next_action_at: istNeu ? eingang.next_action_at : (aktuell.next_action_at || ''),
    notiz: aktuell.notiz ?? '',
    berichte_drive_url: aktuell.berichte_drive_url || '',
  } }];

